for ln in P.split('\n'):
  code,naam,reg,fu,sf,geh,sc,pers,kink,ro,it,er,th=ln.split('|')
  feit=f"Regio: {reg}. Functie: {fu}. Sfeer: {sf}. Geheim: {geh}. Scènetypes: {sc}. Personages: {pers.replace(';',', ')}. Kink-plek: {kink}. Verhaalhaken: romance: {ro}; intrige: {it}; erotiek: {er}; thriller: {th}."
  refs=[f'REG-{reg}']+[p for p in pers.split(';') if p.startswith('PER-')]
  import re
  refs+=re.findall(r'\(((?:RIT|PLEK-LICH|SEKTE)-[a-z\-]+)\)',kink)
  A(code,'Regio' if code.startswith('STAD') else 'Land',naam,feit+GR,'steden en plekken',';'.join(r for r in dict.fromkeys(refs) if r),functie='ID')
# kaart
K=[('KAART-afstanden','Afstanden','Saelith-Hallowyn 120 km (4 dagen te voet, 2 per kar, 1 dag per bark). Saelith-Brakhaven 300 km (6 dagen per schip). Saelith-Kaldrun 400 km (12 dagen). Saelith-Tuaro 350 km (10 dagen). Saelith-Qesh 600 km (20 dagen per karavaan). Tuaro-Ves-Anath 80 km jungle (5 dagen). Kaldrun-Amberpas 60 km. Brakhaven-Stille eilanden 250 km (5 dagen zeilen). Skerra-koerier: Saelith-Kaldrun in 1 dag.','REG-overzicht'),
('KAART-routes','Reisroutes','De Ysmer (rivier en binnenzee) is de hoofdweg; de Pelgrimsweg naar Hoogvrouwe; de Kustweg langs de Zoutkust; de Karavaanweg door de Rosse; Oevrin-slikgangen (geheim); Grijswortel-paden door Groenmuil (geheim); de Amberpas naar Kharvos.','PLEK-LICH-pelgrimsweg;LIJN-verzet;PLEK-amberpas'),
('KAART-klimaat','Klimaat','Noord: lange winters, sneeuw. Midden: gematigd, lenteoverstromingen. West: mist en stormen. Oost: tropische regen. Zuid: hete dagen, koude nachten. Kharvos: droog, kookheet in de zegelschaduw.','REG-overzicht'),
('KAART-zegellijnen','Zegellijnen op de kaart','Vanuit Ves-Anath lopen zeven zegellijnen als spaken naar de grote tempels (Saelith, Kaldrun, Brakhaven, Tuaro, Merk, Ijsgraf, Orvane). De Rosse rond Qesh en de Stille eilanden liggen buiten de lijnen; Kharvos ligt in de zegelschaduw.','GEH-zegel;LIJN-overzicht;PLEK-ves-anath-ruines'),
('KAART-seizoenen','Reisseizoenen','Lente: delta onbegaanbaar (overstroming). Zomer: beste reistijd, Lampenfeest. Herfst: oogst, stormen op zee. Winter: Amberpas dicht, dus Kharvos valt in de zomer aan. Een quest-klok: de pas sluit in de Rotmaan.','KAL-kalender;PLEK-amberpas'),
('KAART-grenzen','Grenzen en tolposten','Kaldra-tolposten in de bergen, Orde-posten op de Ysmer (registercontrole), Mirre-havens (tiende). Reizen zonder papier is voor mannen onmogelijk, voor vrouwen duur.','RECHT-gastrecht;WET-smokkel')]
for c_,o,f,r in K: A(c_,'Land',o,f+GR,'kaart',r,functie='NAV;INFO')
# taal en namen
T=[('mens-saelith','Saelith-namen: lang en vocaalrijk (Ithrael, Imra, Thessaly); hoftaal met eretitels.'),('mens-ambergaard','Ambergaard: kort en nuchter (Liora, Dagny, Bram, Hilde); dialect met verkleinwoorden.'),('mens-hoogvrouwe','Hoogvrouwe: harde medeklinkers (Brannoch, Runa, Yfke); krijgstaal.'),('mens-zoutkust','Zoutkust: zeemanstaal, bijnamen (Sef, Tobin, Jorrit); veel leenwoorden van Sael-mor.'),('aelthir','Aelthir: zingend, met vijf tonen; namen met ae/th (Vaelorn, Sorn).'),('karruk','Karrûk: keelklanken, namen van één lettergreep (Gath, Yssa, Khorr).'),('dhurn','Dhurn: rotstaal, namen met -a/-ik (Borga, Tavik).'),('sael-mor','Sael-mor: getijwoorden, namen met w/l (Wenna, Orla).'),('grauwen','Grauwen: mensentaal met eigen zorgwoorden; dragen gestolen of verkorte namen (Mott, Vell).'),('ishvar','Ishvar: woestijntaal, namen met -ar/-ir zonder gave-betekenis (Tamar, Nadir); verwarrend voor Velmara.'),('vathren','Vathren: spreken weinig; namen naar hartslag (Ruy, Orl).'),('kluwer','Kluwer: klik- en zoemtaal; mensen kunnen ze alleen nadoen (Zzi, Yrr).'),('myrrhen','Myrrhen: fluisterend, de namen van hun doden (Lys, Dov, Ondal).'),('oevrin','Oevrin: borrelend, onderwater (Glu, Vaa).'),('tharn','Tharn: traag en diep, namen naar dijken (Bor, Lunn, Oela).'),('orrim','Orrim: knarsend, namen naar kristallen (Sha, Dru).'),('skerra','Skerra: fluitende roep-taal (Ka, Hilt, Ilwa).'),('ves-lethi','Ves-Lethi: nemen de taal van wie ze nabootsen; echte namen dubbel (Ommo, Iska, Nara).'),('gaven-man','Gaven-mannen: kiezen -ir of -as; -ir voor macht, -as voor gunst (Morvane-ir, Aeron-as).'),('kharvos','Kharvos: mannentaal; vrouwen hebben geen eigen naam, alleen die van hun bezitter.')]
for s,f in T: A(f'TAAL-{s}','Cultuur',f'Taal en namen: {s}',f+GR,'naamgeving','CUL-taal-namen',functie='ID')
# 801
N=[('NU-conflict-zegelbinding','Conflict: de Zegelbinding','Ithrael wil de Zegel opnieuw binden met Sterrensteen (Orrim) en een gloeiende vrouw (Liora). Wie wil wat: Orde (behoud), Varenne (falen, dan monopolie), Morvane-ir (breken), Stille Twijfel (bekennen). Klok: de binding moet voor de Lege Dag van 802.','PER-ithrael;PER-liora-profiel;PER-orrim-sha;FEEST-lege-dag;RIT-zegelbinding'),
('NU-conflict-kharvos','Conflict: Kharvos aan de pas','Drask moet toeslaan voordat zijn ziekte hem doodt; Kaldra heeft te weinig Strijdzaad; Rhun-ir kan de pas houden met zijn stem, maar dan is het geheim uit.','PER-drask;PER-brannoch;PER-sch-rhun;PLEK-amberpas'),
('NU-conflict-schuld','Conflict: de Orde-schuld','Selvine eist de schuld van de Orde op in gunstbrieven; als ze ze op de markt gooit, crasht de valuta. Intrige: Kreel, Vessa en Imra spelen elk een kant.','PER-selvine;ORDE-financien;PER-sch-kreel'),
('NU-conflict-teo','Conflict: Teo','Iedereen wil Teo: de Orde (Lijngraver, bijgeschreven), Varenne (fokman), Morvane-ir (een gave die hij kan binden), Liora (haar broer). Klok: Ysolde haalt hem bij de volgende maan.','PER-teo;PER-sch-ysolde;PER-selvine'),
('NU-conflict-lekken','Conflict: de lekken','Lekgeboorten nemen toe; Vathren worden gejaagd; lampen flikkeren. De Lampenwakers groeien.','SEKTE-lampenwakers;GEB-r10-lekgeboorten;VOLK-vathren'),
('NU-conflict-stallen','Conflict: stalopstand','De Vaderlingen in Merk plannen een opstand; Bram en Wessel kennen het teken. Ankerwortel-bewijs zou de opstand legitimeren.','SEKTE-vaderlingen;PER-bram;PER-gew-wessel;WET-ankerwortel'),
('NU-conflict-veslethi','Conflict: een vruchtbare man buiten het systeem','Als bekend wordt dat Ves-Lethi in mannelijke fase vruchtbaar zijn (Ommo), wil elk huis er een. Dat breekt de Orde.','PER-veslethi-ommo;VOLK-ves-lethi'),
('NU-volgende-crisis','De volgende crisis','Waarschijnlijk: de Orde-valuta crasht (Varenne), Kharvos valt in de zomer aan en Morvane-ir opent Lisk voor hen, terwijl de Zegelbinding mislukt en een lek een hele stad treft. Drie klokken die samen vallen in de Bloedmaan van 802.','NU-conflict-schuld;NU-conflict-kharvos;NU-conflict-zegelbinding'),
('NU-wie-wil-wat','Wie wil wat (801)','Ithrael: behoud. Vessa: opvolging. Imra: waarheid. Selvine: monopolie. Ondessa: vrije zee. Brannoch: oorlog winnen. Khaled-Ir: onafhankelijkheid. Morvane-ir: heerschappij. Drask: overleven via roof. Liora: Teo en de waarheid. Teo: vrijheid. Bram: vrijheid. Sef: Liora en geld.','HAAK-PER-intrige')]
for c_,o,f,r in N: A(c_,'Verhaal',o,f+GR,'de huidige tijd',r,functie='POL')
A('HAAK-G4-overzicht','Verhaal','Verhaalhaken per plek (overzicht)','Elke STAD-/PLEK-rij heeft haken voor romance, intrige, erotiek en thriller. Vertrouwde plekken (Hallowyn, herberg, Brakhaven, Kaldrun) dragen de herkenbare gevoelens; vreemde plekken (Korf, Veenhallen, Spiegelhuis, Schaduwvlakte) zijn gedoseerd contrast met een duidelijke functie in de quest.'+GR,'genrehaken','STAD-hallowyn;PLEK-zoutkust-herberg;STAD-brakhaven;STAD-kaldrun;PLEK-groen-korf;PLEK-nevel-veen;PLEK-kharvos-spiegelhuis')
HR=[('saelith','Romance: een Ontvangster en een vluchtende gaven-man; intrige: opvolging van Ithrael; erotiek: Lampenfeest; thriller: de Stille Hand.'),('ambergaard','Romance: eigenares en stalman; intrige: schuld en Varenne; erotiek: Oogstbed; thriller: stalopstand en Teo\'s ophaling.'),('hoogvrouwe','Romance: krijgsvrouw en Karrûk; intrige: Rhun-ir; erotiek: bonten in de winter; thriller: Drask op de pas.'),('zoutkust','Romance: Sef en Liora; intrige: Ondessa\'s hypocrisie; erotiek: vrije mannen, maskers; thriller: Zoutkelders.'),('groenmuil','Romance: Ruy en Liora; intrige: Sorns verraad; erotiek: watervallen; thriller: askouden bij Ves-Anath.'),('rosse','Romance: Ishvar-trouw als verleiding; intrige: Seri en Morvane-ir; erotiek: harem-gunst; thriller: Zandput en de krater.'),('kharvos','Romance: Ommo en een Sael-mor; intrige: Drask-Morvane-pact; erotiek: Vuurkamp (gedoseerd); thriller: gevangenschap en ontsnapping.'),('stille','Romance: zusterliefde; intrige: Ennia\'s missie; erotiek: ingetogen; thriller: de kluis ontdooit.')]
for g,f in HR: A(f'HAAK-REG-{g}','Verhaal',f'Verhaalhaken: {g.capitalize()}',f+GR,'genrehaken per regio',f'REG-{g}')
X=[('PLEK-saelith-gondelwerf','De Gondelwerf van Saelith','saelith','Werf en schuilplaats van veermannen; Pell kent de onderwaterpoort van de tempel. Haak: inbraak in de tempel (thriller), veerman en novice (romance).','PER-gew-pell'),
('PLEK-hoog-wolvenhut','De Wolvenhut','hoogvrouwe','Berghut aan de Pelgrimsweg; sneeuwstorm sluit reizigers dagen in. Haak: gedwongen nabijheid (romance/erotiek), een moord in de storm (thriller).','PLEK-LICH-pelgrimsweg'),
('PLEK-rosse-zonnepaleis','Het Zonnepaleis','rosse','Harem-paleis van Khaled-Ir; tuinen, waterspelen, spionnen achter tralies. Haak: Liora\'s prijs (een seizoen), Seri\'s geheim.','PER-khaled-profiel;PER-khaled-pact'),
('PLEK-kharvos-grensfort','Grensfort Ashkar','kharvos','Kharvos-fort tegenover de Amberpas; Karrûk-garnizoen dat overloopt als Yssa het vraagt. Haak: verraad van binnenuit.','PER-karruk-yssa;PLEK-amberpas')]
for c_,o,g,f,r in X: A(c_,'Land',o,f'Regio: {g}. '+f+GR,'steden en plekken',f'REG-{g};'+r,functie='ID')
